--
-- Table structure for table `wp_posts`
--

DROP TABLE IF EXISTS `wp_posts`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `wp_posts` (
  `ID` bigint unsigned NOT NULL AUTO_INCREMENT,
  `post_author` bigint unsigned NOT NULL DEFAULT '0',
  `post_date` datetime NOT NULL DEFAULT '0000-00-00 00:00:00',
  `post_date_gmt` datetime NOT NULL DEFAULT '0000-00-00 00:00:00',
  `post_content` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NOT NULL,
  `post_title` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NOT NULL,
  `post_excerpt` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NOT NULL,
  `post_status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NOT NULL DEFAULT 'publish',
  `comment_status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NOT NULL DEFAULT 'open',
  `ping_status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NOT NULL DEFAULT 'open',
  `post_password` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NOT NULL DEFAULT '',
  `post_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NOT NULL DEFAULT '',
  `to_ping` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NOT NULL,
  `pinged` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NOT NULL,
  `post_modified` datetime NOT NULL DEFAULT '0000-00-00 00:00:00',
  `post_modified_gmt` datetime NOT NULL DEFAULT '0000-00-00 00:00:00',
  `post_content_filtered` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NOT NULL,
  `post_parent` bigint unsigned NOT NULL DEFAULT '0',
  `guid` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NOT NULL DEFAULT '',
  `menu_order` int NOT NULL DEFAULT '0',
  `post_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NOT NULL DEFAULT 'post',
  `post_mime_type` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NOT NULL DEFAULT '',
  `comment_count` bigint NOT NULL DEFAULT '0',
  PRIMARY KEY (`ID`),
  KEY `post_name` (`post_name`(191)),
  KEY `type_status_date` (`post_type`,`post_status`,`post_date`,`ID`),
  KEY `post_parent` (`post_parent`),
  KEY `post_author` (`post_author`),
  KEY `type_status_author` (`post_type`,`post_status`,`post_author`)
) ENGINE=InnoDB AUTO_INCREMENT=1057 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_520_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `wp_posts`
--

LOCK TABLES `wp_posts` WRITE;
/*!40000 ALTER TABLE `wp_posts` DISABLE KEYS */;
INSERT INTO `wp_posts` VALUES (2,1,'2026-11-14 07:51:00','2026-11-14 07:51:00','<!-- wp:paragraph -->\n<p>This is an example page. It\'s different from a blog post because it will stay in one place and will show up in your site navigation (in most themes). Most people start with an About page that introduces them to potential site visitors. It might say something like this:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:quote -->\n<blockquote class=\"wp-block-quote\">\n<!-- wp:paragraph -->\n<p>Hi there! I\'m a bike messenger by day, aspiring actor by night, and this is my website. I live in Los Angeles, have a great dog named Jack, and I like pi&#241;a coladas. (And gettin\' caught in the rain.)</p>\n<!-- /wp:paragraph -->\n</blockquote>\n<!-- /wp:quote -->\n\n<!-- wp:paragraph -->\n<p>...or something like this:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:quote -->\n<blockquote class=\"wp-block-quote\">\n<!-- wp:paragraph -->\n<p>The XYZ Doohickey Company was founded in 1971, and has been providing quality doohickeys to the public ever since. Located in Gotham City, XYZ employs over 2,000 people and does all kinds of awesome things for the Gotham community.</p>\n<!-- /wp:paragraph -->\n</blockquote>\n<!-- /wp:quote -->\n\n<!-- wp:paragraph -->\n<p>As a new WordPress user, you should go to <a href=\"http://localhost:8090/wp-admin/\">your dashboard</a> to delete this page and create new pages for your content. Have fun!</p>\n<!-- /wp:paragraph -->','Sample Page','','publish','closed','open','','sample-page','','','2026-11-14 07:51:00','2026-11-14 07:51:00','',0,'http://localhost:8090/?page_id=2',0,'page','',0),(3,1,'2026-11-14 07:51:00','2026-11-14 07:51:00','<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Who we are</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class=\"privacy-policy-tutorial\">Suggested text: </strong>Our website address is: http://localhost:8090.</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Comments</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class=\"privacy-policy-tutorial\">Suggested text: </strong>When visitors leave comments on the site we collect the data shown in the comments form, and also the visitor&#8217;s IP address and browser user agent string to help spam detection.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>An anonymized string created from your email address (also called a hash) may be provided to the Gravatar service to see if you are using it. The Gravatar service privacy policy is available here: https://automattic.com/privacy/. After approval of your comment, your profile picture is visible to the public in the context of your comment.</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Media</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class=\"privacy-policy-tutorial\">Suggested text: </strong>If you upload images to the website, you should avoid uploading images with embedded location data (EXIF GPS) included. Visitors to the website can download and extract any location data from images on the website.</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Cookies</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class=\"privacy-policy-tutorial\">Suggested text: </strong>If you leave a comment on our site you may opt-in to saving your name, email address and website in cookies. These are for your convenience so that you do not have to fill in your details again when you leave another comment. These cookies will last for one year.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>If you visit our login page, we will set a temporary cookie to determine if your browser accepts cookies. This cookie contains no personal data and is discarded when you close your browser.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>When you log in, we will also set up several cookies to save your login information and your screen display choices. Login cookies last for two days, and screen options cookies last for a year. If you select &quot;Remember Me&quot;, your login will persist for two weeks. If you log out of your account, the login cookies will be removed.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>If you edit or publish an article, an additional cookie will be saved in your browser. This cookie includes no personal data and simply indicates the post ID of the article you just edited. It expires after 1 day.</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Embedded content from other websites</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class=\"privacy-policy-tutorial\">Suggested text: </strong>Articles on this site may include embedded content (e.g. videos, images, articles, etc.). Embedded content from other websites behaves in the exact same way as if the visitor has visited the other website.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>These websites may collect data about you, use cookies, embed additional third-party tracking, and monitor your interaction with that embedded content, including tracking your interaction with the embedded content if you have an account and are logged in to that website.</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Who we share your data with</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class=\"privacy-policy-tutorial\">Suggested text: </strong>If you request a password reset, your IP address will be included in the reset email.</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">How long we retain your data</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class=\"privacy-policy-tutorial\">Suggested text: </strong>If you leave a comment, the comment and its metadata are retained indefinitely. This is so we can recognize and approve any follow-up comments automatically instead of holding them in a moderation queue.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>For users that register on our website (if any), we also store the personal information they provide in their user profile. All users can see, edit, or delete their personal information at any time (except they cannot change their username). Website administrators can also see and edit that information.</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">What rights you have over your data</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class=\"privacy-policy-tutorial\">Suggested text: </strong>If you have an account on this site, or have left comments, you can request to receive an exported file of the personal data we hold about you, including any data you have provided to us. You can also request that we erase any personal data we hold about you. This does not include any data we are obliged to keep for administrative, legal, or security purposes.</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Where your data is sent</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class=\"privacy-policy-tutorial\">Suggested text: </strong>Visitor comments may be checked through an automated spam detection service.</p>\n<!-- /wp:paragraph -->\n','Privacy Policy','','draft','closed','open','','privacy-policy','','','2026-11-14 07:51:00','2026-11-14 07:51:00','',0,'http://localhost:8090/?page_id=3',0,'page','',0),(4,0,'2026-11-14 07:51:23','2026-11-14 07:51:23','','woocommerce-placeholder','','inherit','open','closed','','woocommerce-placeholder','','','2026-11-14 07:51:23','2026-11-14 07:51:23','',0,'http://localhost:8090/wp-content/uploads/2026/11/woocommerce-placeholder.webp',0,'attachment','image/webp',0),(5,1,'2026-11-14 07:51:24','2026-11-14 07:51:24','','Cửa hàng','','publish','closed','closed','','shop','','','2026-11-15 13:26:06','2026-11-15 06:26:06','',0,'http://localhost:8090/?page_id=5',0,'page','',0),(6,1,'2026-11-14 07:51:24','2026-11-14 07:51:24','<!-- wp:woocommerce/cart -->\n<div class=\"wp-block-woocommerce-cart alignwide is-loading\"><!-- wp:woocommerce/filled-cart-block -->\n<div class=\"wp-block-woocommerce-filled-cart-block\"><!-- wp:woocommerce/cart-items-block -->\n<div class=\"wp-block-woocommerce-cart-items-block\"><!-- wp:woocommerce/cart-line-items-block -->\n<div class=\"wp-block-woocommerce-cart-line-items-block\"></div>\n<!-- /wp:woocommerce/cart-line-items-block -->\n\n<!-- wp:woocommerce/product-collection {\"queryId\":0,\"query\":{\"perPage\":3,\"pages\":1,\"offset\":0,\"postType\":\"product\",\"order\":\"asc\",\"orderBy\":\"title\",\"search\":\"\",\"exclude\":[],\"inherit\":false,\"taxQuery\":[],\"isProductCollectionBlock\":true,\"featured\":false,\"woocommerceOnSale\":false,\"woocommerceStockStatus\":[\"instock\",\"outofstock\",\"onbackorder\"],\"woocommerceAttributes\":[],\"woocommerceHandPickedProducts\":[],\"filterable\":false,\"relatedBy\":{\"categories\":true,\"tags\":true}},\"tagName\":\"div\",\"displayLayout\":{\"type\":\"flex\",\"columns\":3,\"shrinkColumns\":true},\"dimensions\":{\"widthType\":\"fill\"},\"collection\":\"woocommerce/product-collection/cross-sells\",\"hideControls\":[\"filterable\"],\"queryContextIncludes\":[\"collection\"]} -->\n<div class=\"wp-block-woocommerce-product-collection\"><!-- wp:heading {\"textAlign\":\"left\",\"style\":{\"spacing\":{\"margin\":{\"bottom\":\"1rem\"}}}} -->\n<h2 class=\"wp-block-heading has-text-align-left\" style=\"margin-bottom:1rem\">You may be interested in&hellip;</h2>\n\n<!-- /wp:heading -->\n\n<!-- wp:woocommerce/product-template -->\n<!-- wp:woocommerce/product-image {\"showSaleBadge\":false,\"imageSizing\":\"thumbnail\",\"isDescendentOfQueryLoop\":true} -->\n<!-- wp:woocommerce/product-sale-badge {\"align\":\"right\"} /-->\n<!-- /wp:woocommerce/product-image -->\n\n<!-- wp:post-title {\"textAlign\":\"center\",\"isLink\":true,\"style\":{\"spacing\":{\"margin\":{\"bottom\":\"0.75rem\",\"top\":\"0\"}},\"typography\":{\"lineHeight\":\"1.4\"}},\"fontSize\":\"medium\",\"__woocommerceNamespace\":\"woocommerce/product-collection/product-title\"} /-->\n\n<!-- wp:woocommerce/product-price {\"isDescendentOfQueryLoop\":true,\"textAlign\":\"center\",\"fontSize\":\"small\"} /-->\n\n<!-- wp:woocommerce/product-button {\"textAlign\":\"center\",\"isDescendentOfQueryLoop\":true,\"fontSize\":\"small\"} /-->\n<!-- /wp:woocommerce/product-template --></div>\n<!-- /wp:woocommerce/product-collection --></div>\n\n<!-- /wp:woocommerce/cart-items-block -->\n\n<!-- wp:woocommerce/cart-totals-block -->\n<div class=\"wp-block-woocommerce-cart-totals-block\"><!-- wp:woocommerce/cart-order-summary-block -->\n<div class=\"wp-block-woocommerce-cart-order-summary-block\"><!-- wp:woocommerce/cart-order-summary-heading-block -->\n<div class=\"wp-block-woocommerce-cart-order-summary-heading-block\"></div>\n<!-- /wp:woocommerce/cart-order-summary-heading-block -->\n\n<!-- wp:woocommerce/cart-order-summary-coupon-form-block -->\n<div class=\"wp-block-woocommerce-cart-order-summary-coupon-form-block\"></div>\n<!-- /wp:woocommerce/cart-order-summary-coupon-form-block -->\n\n<!-- wp:woocommerce/cart-order-summary-subtotal-block -->\n<div class=\"wp-block-woocommerce-cart-order-summary-subtotal-block\"></div>\n<!-- /wp:woocommerce/cart-order-summary-subtotal-block -->\n\n<!-- wp:woocommerce/cart-order-summary-fee-block -->\n<div class=\"wp-block-woocommerce-cart-order-summary-fee-block\"></div>\n<!-- /wp:woocommerce/cart-order-summary-fee-block -->\n\n<!-- wp:woocommerce/cart-order-summary-discount-block -->\n<div class=\"wp-block-woocommerce-cart-order-summary-discount-block\"></div>\n<!-- /wp:woocommerce/cart-order-summary-discount-block -->\n\n<!-- wp:woocommerce/cart-order-summary-shipping-block -->\n<div class=\"wp-block-woocommerce-cart-order-summary-shipping-block\"></div>\n<!-- /wp:woocommerce/cart-order-summary-shipping-block -->\n\n<!-- wp:woocommerce/cart-order-summary-taxes-block -->\n<div class=\"wp-block-woocommerce-cart-order-summary-taxes-block\"></div>\n<!-- /wp:woocommerce/cart-order-summary-taxes-block --></div>\n<!-- /wp:woocommerce/cart-order-summary-block -->\n\n<!-- wp:woocommerce/cart-express-payment-block -->\n<div class=\"wp-block-woocommerce-cart-express-payment-block\"></div>\n<!-- /wp:woocommerce/cart-express-payment-block -->\n\n<!-- wp:woocommerce/proceed-to-checkout-block -->\n<div class=\"wp-block-woocommerce-proceed-to-checkout-block\"></div>\n<!-- /wp:woocommerce/proceed-to-checkout-block -->\n\n<!-- wp:woocommerce/cart-accepted-payment-methods-block -->\n<div class=\"wp-block-woocommerce-cart-accepted-payment-methods-block\"></div>\n<!-- /wp:woocommerce/cart-accepted-payment-methods-block --></div>\n<!-- /wp:woocommerce/cart-totals-block --></div>\n<!-- /wp:woocommerce/filled-cart-block -->\n\n<!-- wp:woocommerce/empty-cart-block -->\n<div class=\"wp-block-woocommerce-empty-cart-block\"><!-- wp:heading {\"textAlign\":\"center\",\"className\":\"with-empty-cart-icon wc-block-cart__empty-cart__title\"} -->\n<h2 class=\"wp-block-heading has-text-align-center with-empty-cart-icon wc-block-cart__empty-cart__title\">Your cart is currently empty!</h2>\n<!-- /wp:heading -->\n\n<!-- wp:separator {\"className\":\"is-style-dots\"} -->\n<hr class=\"wp-block-separator has-alpha-channel-opacity is-style-dots\" />\n<!-- /wp:separator -->\n\n<!-- wp:heading {\"textAlign\":\"center\"} -->\n<h2 class=\"wp-block-heading has-text-align-center\">New in store</h2>\n<!-- /wp:heading -->\n\n<!-- wp:woocommerce/product-new {\"columns\":4,\"rows\":1} /--></div>\n<!-- /wp:woocommerce/empty-cart-block --></div>\n<!-- /wp:woocommerce/cart -->','Giỏ hàng','','publish','closed','closed','','cart','','','2026-11-15 13:26:06','2026-11-15 06:26:06','',0,'http://localhost:8090/?page_id=6',0,'page','',0),(7,1,'2026-11-14 07:51:24','2026-11-14 07:51:24','<!-- wp:woocommerce/checkout -->\n<div class=\"wp-block-woocommerce-checkout alignwide wc-block-checkout is-loading\"><!-- wp:woocommerce/checkout-fields-block -->\n<div class=\"wp-block-woocommerce-checkout-fields-block\"><!-- wp:woocommerce/checkout-express-payment-block -->\n<div class=\"wp-block-woocommerce-checkout-express-payment-block\"></div>\n<!-- /wp:woocommerce/checkout-express-payment-block -->\n\n<!-- wp:woocommerce/checkout-contact-information-block -->\n<div class=\"wp-block-woocommerce-checkout-contact-information-block\"></div>\n<!-- /wp:woocommerce/checkout-contact-information-block -->\n\n<!-- wp:woocommerce/checkout-shipping-method-block -->\n<div class=\"wp-block-woocommerce-checkout-shipping-method-block\"></div>\n<!-- /wp:woocommerce/checkout-shipping-method-block -->\n\n<!-- wp:woocommerce/checkout-pickup-options-block -->\n<div class=\"wp-block-woocommerce-checkout-pickup-options-block\"></div>\n<!-- /wp:woocommerce/checkout-pickup-options-block -->\n\n<!-- wp:woocommerce/checkout-shipping-address-block -->\n<div class=\"wp-block-woocommerce-checkout-shipping-address-block\"></div>\n<!-- /wp:woocommerce/checkout-shipping-address-block -->\n\n<!-- wp:woocommerce/checkout-billing-address-block -->\n<div class=\"wp-block-woocommerce-checkout-billing-address-block\"></div>\n<!-- /wp:woocommerce/checkout-billing-address-block -->\n\n<!-- wp:woocommerce/checkout-shipping-methods-block -->\n<div class=\"wp-block-woocommerce-checkout-shipping-methods-block\"></div>\n<!-- /wp:woocommerce/checkout-shipping-methods-block -->\n\n<!-- wp:woocommerce/checkout-payment-block -->\n<div class=\"wp-block-woocommerce-checkout-payment-block\"></div>\n<!-- /wp:woocommerce/checkout-payment-block -->\n\n<!-- wp:woocommerce/checkout-additional-information-block -->\n<div class=\"wp-block-woocommerce-checkout-additional-information-block\"></div>\n<!-- /wp:woocommerce/checkout-additional-information-block -->\n\n<!-- wp:woocommerce/checkout-order-note-block -->\n<div class=\"wp-block-woocommerce-checkout-order-note-block\"></div>\n<!-- /wp:woocommerce/checkout-order-note-block -->\n\n<!-- wp:woocommerce/checkout-terms-block -->\n<div class=\"wp-block-woocommerce-checkout-terms-block\"></div>\n<!-- /wp:woocommerce/checkout-terms-block -->\n\n<!-- wp:woocommerce/checkout-actions-block -->\n<div class=\"wp-block-woocommerce-checkout-actions-block\"></div>\n<!-- /wp:woocommerce/checkout-actions-block --></div>\n<!-- /wp:woocommerce/checkout-fields-block -->\n\n<!-- wp:woocommerce/checkout-totals-block -->\n<div class=\"wp-block-woocommerce-checkout-totals-block\"><!-- wp:woocommerce/checkout-order-summary-block -->\n<div class=\"wp-block-woocommerce-checkout-order-summary-block\"><!-- wp:woocommerce/checkout-order-summary-cart-items-block -->\n<div class=\"wp-block-woocommerce-checkout-order-summary-cart-items-block\"></div>\n<!-- /wp:woocommerce/checkout-order-summary-cart-items-block -->\n\n<!-- wp:woocommerce/checkout-order-summary-coupon-form-block -->\n<div class=\"wp-block-woocommerce-checkout-order-summary-coupon-form-block\"></div>\n<!-- /wp:woocommerce/checkout-order-summary-coupon-form-block -->\n\n<!-- wp:woocommerce/checkout-order-summary-subtotal-block -->\n<div class=\"wp-block-woocommerce-checkout-order-summary-subtotal-block\"></div>\n<!-- /wp:woocommerce/checkout-order-summary-subtotal-block -->\n\n<!-- wp:woocommerce/checkout-order-summary-fee-block -->\n<div class=\"wp-block-woocommerce-checkout-order-summary-fee-block\"></div>\n<!-- /wp:woocommerce/checkout-order-summary-fee-block -->\n\n<!-- wp:woocommerce/checkout-order-summary-discount-block -->\n<div class=\"wp-block-woocommerce-checkout-order-summary-discount-block\"></div>\n<!-- /wp:woocommerce/checkout-order-summary-discount-block -->\n\n<!-- wp:woocommerce/checkout-order-summary-shipping-block -->\n<div class=\"wp-block-woocommerce-checkout-order-summary-shipping-block\"></div>\n<!-- /wp:woocommerce/checkout-order-summary-shipping-block -->\n\n<!-- wp:woocommerce/checkout-order-summary-taxes-block -->\n<div class=\"wp-block-woocommerce-checkout-order-summary-taxes-block\"></div>\n<!-- /wp:woocommerce/checkout-order-summary-taxes-block --></div>\n<!-- /wp:woocommerce/checkout-order-summary-block --></div>\n<!-- /wp:woocommerce/checkout-totals-block --></div>\n<!-- /wp:woocommerce/checkout -->','Thanh toán','','publish','closed','closed','','checkout','','','2026-11-15 13:26:06','2026-11-15 06:26:06','',0,'http://localhost:8090/?page_id=7',0,'page','',0),(8,1,'2026-11-14 07:51:24','2026-11-14 07:51:24','<!-- wp:shortcode -->[woocommerce_my_account]<!-- /wp:shortcode -->','Tài khoản của tôi','','publish','closed','closed','','my-account','','','2026-11-15 13:26:06','2026-11-15 06:26:06','',0,'http://localhost:8090/?page_id=8',0,'page','',0),(9,1,'2026-11-14 07:51:24','0000-00-00 00:00:00','<!-- wp:paragraph -->\n<p><b>This is a sample page.</b></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Overview</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Our refund and returns policy lasts 30 days. If 30 days have passed since your purchase, we can’t offer you a full refund or exchange.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>To be eligible for a return, your item must be unused and in the same condition that you received it. It must also be in the original packaging.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Several types of goods are exempt from being returned. Perishable goods such as food, flowers, newspapers or magazines cannot be returned. We also do not accept products that are intimate or sanitary goods, hazardous materials, or flammable liquids or gases.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Additional non-returnable items:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul>\n<li>Gift cards</li>\n<li>Downloadable software products</li>\n<li>Some health and personal care items</li>\n</ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p>To complete your return, we require a receipt or proof of purchase.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Please do not send your purchase back to the manufacturer.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>There are certain situations where only partial refunds are granted:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul>\n<li>Book with obvious signs of use</li>\n<li>CD, DVD, VHS tape, software, video game, cassette tape, or vinyl record that has been opened.</li>\n<li>Any item not in its original condition, is damaged or missing parts for reasons not due to our error.</li>\n<li>Any item that is returned more than 30 days after delivery</li>\n</ul>\n<!-- /wp:list -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Refunds</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Once your return is received and inspected, we will send you an email to notify you that we have received your returned item. We will also notify you of the approval or rejection of your refund.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>If you are approved, then your refund will be processed, and a credit will automatically be applied to your credit card or original method of payment, within a certain amount of days.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Late or missing refunds</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>If you haven’t received a refund yet, first check your bank account again.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Then contact your credit card company, it may take some time before your refund is officially posted.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Next contact your bank. There is often some processing time before a refund is posted.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>If you’ve done all of this and you still have not received your refund yet, please contact us at {email address}.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Sale items</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Only regular priced items may be refunded. Sale items cannot be refunded.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Exchanges</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>We only replace items if they are defective or damaged. If you need to exchange it for the same item, send us an email at {email address} and send your item to: {physical address}.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Gifts</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>If the item was marked as a gift when purchased and shipped directly to you, you’ll receive a gift credit for the value of your return. Once the returned item is received, a gift certificate will be mailed to you.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>If the item wasn’t marked as a gift when purchased, or the gift giver had the order shipped to themselves to give to you later, we will send a refund to the gift giver and they will find out about your return.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Shipping returns</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>To return your product, you should mail your product to: {physical address}.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>You will be responsible for paying for your own shipping costs for returning your item. Shipping costs are non-refundable. If you receive a refund, the cost of return shipping will be deducted from your refund.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Depending on where you live, the time it may take for your exchanged product to reach you may vary.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>If you are returning more expensive items, you may consider using a trackable shipping service or purchasing shipping insurance. We don’t guarantee that we will receive your returned item.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Need help?</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Contact us at {email} for questions related to refunds and returns.</p>\n<!-- /wp:paragraph -->','Refund and Returns Policy','','draft','closed','closed','','refund_returns','','','2026-11-14 07:51:24','0000-00-00 00:00:00','',0,'http://localhost:8090/?page_id=9',0,'page','',0),(10,0,'2026-11-14 14:51:46','2026-11-14 07:51:46','','Trang chủ','','publish','closed','closed','','home','','','2026-11-14 14:51:46','2026-11-14 07:51:46','',0,'http://localhost:8090/?page_id=10',0,'page','',0),(11,0,'2026-11-14 14:51:46','2026-11-14 07:51:46','<!-- wp:html --><div class=\"f-wrap\"><div class=\"f-about-grid\">\n<div>\n<span class=\"f-kicker\" style=\"color:#b8845a;font-weight:700;letter-spacing:2.5px;text-transform:uppercase;font-size:12px\">Kể từ 2016</span>\n<h2>Nội thất dành cho nhịp sống mỗi ngày</h2>\n<p>DeSpace bắt đầu từ một xưởng thiết kế nội thất với ý tưởng giản dị: nội thất cao cấp được thiết kế chỉn chu, kết hợp trực quan hóa không gian thực tế tăng cường 3D/AR để khách hàng hình dung trọn vẹn nhất trong ngôi nhà của mình.</p>\n<p>Chúng tôi tuyển chọn các dòng gỗ đạt chứng nhận FSC, vải đạt chuẩn OEKO-TEX và thép gia công tinh tế. Mỗi thiết kế đều được thử nghiệm và hoàn thiện tỉ mỉ trước khi đến tay bạn.</p>\n<p><strong>DeSpace Sáng lập &amp; Giám đốc thiết kế:</strong> Tư vấn trực tiếp không gian sống &amp; hoàn thiện nội thất cao cấp.</p>\n<a class=\"f-btn f-btn--primary\" href=\"/shop/\">Khám phá bộ sưu tập</a>\n</div>\n<div><img src=\"/wp-content/uploads/hero.jpg\" alt=\"Studio DeSpace\" /></div>\n</div></div><!-- /wp:html -->','Về DeSpace','','publish','closed','closed','','ve-despace','','','2026-11-14 20:05:34','2026-11-14 13:05:34','',0,'http://localhost:8090/?page_id=11',0,'page','',0),(12,0,'2026-11-14 14:51:46','2026-11-14 07:51:46','<!-- wp:html -->\n<div class=\"f-wrap f-contact-luxury-page\">\n    <!-- 1. Showroom &amp; Founder Hero Card -->\n    <div class=\"ds-contact-hero-card\">\n        <div class=\"ds-contact-hero-badge\">DeSpace ARCHITECTURAL SANCTUARY</div>\n        <h2 class=\"ds-contact-hero-title\">Không Gian Sáng Tạo &amp; Showroom Trải Nghiệm 3D/AR</h2>\n        <p class=\"ds-contact-hero-subtitle\">Nơi khởi nguồn cho những không gian sống đậm chất Scandinavian, Muji Serenity &amp; Quiet Luxury. Chúng tôi sẵn sàng đồng hành cùng bạn từ bản vẽ ý tưởng đến hiện thực hóa từng chi tiết nội thất tinh xảo.</p>\n        \n        <div class=\"ds-contact-founder-strip\">\n            <div class=\"ds-founder-avatar\">DS</div>\n            <div class=\"ds-founder-info\">\n                <strong>DeSpace Sáng lập &amp; Giám đốc thiết kế</strong>\n                <span>Tư vấn trực tiếp không gian sống &amp; hoàn thiện nội thất cao cấp</span>\n            </div>\n        </div>\n    </div>\n\n    <!-- 2. Grid: Showroom Details &amp; Booking Form -->\n    <div class=\"f-contact-grid ds-contact-main-grid\">\n        <!-- Col Left: Showroom Directory &amp; Facilities -->\n        <div class=\"f-contact-info ds-showroom-info-box\">\n            <h3 class=\"ds-box-heading\">Thông Tin Showroom &amp; Đón Tiếp</h3>\n            <ul class=\"ds-info-list\">\n                <li>\n                    <span class=\"ds-info-icon\">📍</span>\n                    <div>\n                        <strong>Địa chỉ Showroom:</strong>\n                        <p>số 20 ngách 21 ngõ 367, Phố ngô xuân quản, Xã Gia Lâm, Hà Nội</p>\n                        <small class=\"ds-sub-tip\">Thuận tiện di chuyển, cách Học viện Nông nghiệp 500m, gần Vinhomes Ocean Park 1 &amp; 2.</small>\n                    </div>\n                </li>\n                <li>\n                    <span class=\"ds-info-icon\">📞</span>\n                    <div>\n                        <strong>Hotline Tư Vấn 24/7:</strong>\n                        <p><a href=\"tel:0332174590\" class=\"ds-link-highlight\">0332 174 590</a></p>\n                        <small class=\"ds-sub-tip\">Hỗ trợ nhanh qua Zalo, tư vấn kích thước và phối cảnh 3D.</small>\n                    </div>\n                </li>\n                <li>\n                    <span class=\"ds-info-icon\">✉️</span>\n                    <div>\n                        <strong>Hòm thư Tiếp Nhận Bản Vẽ:</strong>\n                        <p><a href=\"mailto:noithat@despace.vn\" class=\"ds-link-highlight\">noithat@despace.vn</a></p>\n                        <small class=\"ds-sub-tip\">Gửi mặt bằng căn hộ, bản vẽ CAD để nhận dự toán trong 24h.</small>\n                    </div>\n                </li>\n                <li>\n                    <span class=\"ds-info-icon\">⏰</span>\n                    <div>\n                        <strong>Giờ Mở Cửa Trải Nghiệm:</strong>\n                        <p>08:30 – 21:30 (Thứ Hai – Chủ Nhật)</p>\n                        <small class=\"ds-sub-tip\">Mở cửa tất cả các ngày trong tuần, kể cả ngày lễ.</small>\n                    </div>\n                </li>\n                <li>\n                    <span class=\"ds-info-icon\">🅿️</span>\n                    <div>\n                        <strong>Tiện Ích Đón Tiếp:</strong>\n                        <p>Bãi đỗ xe ô tô &amp; xe máy an ninh rộng rãi miễn phí, đồ uống tiếp đón cao cấp, iPad Pro trải nghiệm AR 3D thực tế ảo.</p>\n                    </div>\n                </li>\n            </ul>\n\n            <div class=\"ds-dept-directory\">\n                <h4>Danh Bạ Bộ Phận Chuyên Trách</h4>\n                <div class=\"ds-dept-item\">\n                    <strong>Phòng Thiết Kế &amp; Kiến Trúc:</strong>\n                    <span>Hotline: 0332 174 590 (Nhánh 1) | kts@despace.vn</span>\n                </div>\n                <div class=\"ds-dept-item\">\n                    <strong>Phòng Dự Án B2B &amp; Biệt Thự:</strong>\n                    <span>Hotline: 0332 174 590 (Nhánh 2) | b2b@despace.vn</span>\n                </div>\n                <div class=\"ds-dept-item\">\n                    <strong>Phòng Dịch Vụ Khách Hàng &amp; Bảo Hành:</strong>\n                    <span>Bảo hành kết cấu 3 năm | support@despace.vn</span>\n                </div>\n            </div>\n        </div>\n\n        <!-- Col Right: Interactive Consultation Form -->\n        <div class=\"f-contact-form ds-booking-form-box\">\n            <h3 class=\"ds-box-heading\">Đặt Lịch Tư Vấn Trực Tiếp</h3>\n            <p class=\"ds-form-intro\">Đặt hẹn để được Giám đốc thiết kế DeSpace đón tiếp và tư vấn riêng giải pháp không gian cho ngôi nhà của bạn.</p>\n\n            \n                <div class=\"ds-form-row\">\n                    <label class=\"f-contact-field\">\n                        <span>Họ và tên *</span>\n                        \n                    </label>\n                    <label class=\"f-contact-field\">\n                        <span>Số điện thoại *</span>\n                        \n                    </label>\n                </div>\n\n                <div class=\"ds-form-row\">\n                    <label class=\"f-contact-field\">\n                        <span>Email nhận báo giá</span>\n                        \n                    </label>\n                    <label class=\"f-contact-field\">\n                        <span>Loại hình không gian</span>\n                        \n                            Căn hộ chung cư\n                            Biệt thự / Liền kề\n                            Nhà phố\n                            Showroom / Văn phòng\n                            Mua lẻ sản phẩm nội thất\n                        \n                    </label>\n                </div>\n\n                <div class=\"ds-form-row\">\n                    <label class=\"f-contact-field\">\n                        <span>Dịch vụ mong muốn</span>\n                        \n                            Trải nghiệm trực tiếp tại Showroom &amp; 3D/AR\n                            Khảo sát &amp; đo đạc thực tế tại nhà\n                            Đóng đồ theo kích thước thiết kế riêng\n                            Thiết kế &amp; thi công nội thất trọn gói\n                        \n                    </label>\n                    <label class=\"f-contact-field\">\n                        <span>Thời gian dự kiến ghé thăm</span>\n                        \n                    </label>\n                </div>\n\n                <label class=\"f-contact-field\">\n                    <span>Lời nhắn &amp; yêu cầu chi tiết</span>\n                    <textarea name=\"contact_message\" rows=\"4\"></textarea>\n                </label>\n\n                <button class=\"f-btn f-btn--primary ds-submit-btn\" type=\"submit\">\n                    <span>Gửi Đăng Ký Tư Vấn Trực Tiếp</span>\n                    \n                </button>\n            \n        </div>\n    </div>\n\n    <!-- 3. Our 4-Step Bespoke Consultation Process -->\n    <div class=\"ds-process-section\">\n        <div class=\"ds-section-head-center\">\n            <span class=\"f-kicker\">QUY TRÌNH CHUYÊN NGHIỆP</span>\n            <h2>4 Bước Đồng Hành Cùng Gia Chủ</h2>\n            <p>Từ những phác thảo ban đầu đến khi từng sản phẩm hoàn thiện được đặt trọn vẹn trong ngôi nhà của bạn.</p>\n        </div>\n        <div class=\"ds-process-grid\">\n            <div class=\"ds-process-card\">\n                <span class=\"ds-step-badge\">01</span>\n                <h4>Lắng Nghe &amp; Thấu Hiểu</h4>\n                <p>Trao đổi về phong cách sống, thói quen sinh hoạt và nhu cầu lưu trữ để định hình giải pháp không gian tối ưu.</p>\n            </div>\n            <div class=\"ds-process-card\">\n                <span class=\"ds-step-badge\">02</span>\n                <h4>Khảo Sát &amp; Demo 3D/AR</h4>\n                <p>Đo đạc hiện trạng, dựng mô hình 3D tỷ lệ 1:1 và cho bạn trải nghiệm sản phẩm đặt trong phòng qua kính AR trước khi quyết định.</p>\n            </div>\n            <div class=\"ds-process-card\">\n                <span class=\"ds-step-badge\">03</span>\n                <h4>Duyệt Mẫu &amp; Báo Giá</h4>\n                <p>Trực tiếp kiểm tra mẫu gỗ sồi, óc chó chuẩn FSC, vải OEKO-TEX và bảng báo giá chi tiết, không phát sinh chi phí.</p>\n            </div>\n            <div class=\"ds-process-card\">\n                <span class=\"ds-step-badge\">04</span>\n                <h4>Chế Tác &amp; Bàn Giao</h4>\n                <p>Gia công tỉ mỉ tại xưởng DeSpace, vận chuyển bọc lót 3 lớp xốp và đội ngũ kỹ thuật viên lắp đặt hoàn thiện sạch sẽ.</p>\n            </div>\n        </div>\n    </div>\n\n    <!-- 4. Interactive Google Maps &amp; Route Guide -->\n    <div class=\"ds-map-section\">\n        <div class=\"ds-map-header\">\n            <div>\n                <h3>Vị Trí Showroom DeSpace Trên Bản Đồ</h3>\n                <p>số 20 ngách 21 ngõ 367, Phố ngô xuân quản, Xã Gia Lâm, Hà Nội</p>\n            </div>\n            <a href=\"https://maps.google.com/?q=số+20+ngách+21+ngõ+367+Phố+ngô+xuân+quản+Gia+Lâm+Hà+Nội\" target=\"_blank\" rel=\"noopener\" class=\"f-btn f-btn--secondary ds-open-maps-btn\">\n                <span>Mở Trên Google Maps</span>\n                \n            </a>\n        </div>\n        <div class=\"ds-map-embed-wrapper\">\n            \n        </div>\n    </div>\n\n    <!-- 5. Showroom FAQ -->\n    <div class=\"ds-faq-section\">\n        <h3 class=\"ds-faq-title\">Câu Hỏi Thường Gặp Khi Ghé Thăm Showroom</h3>\n        <div class=\"ds-faq-grid\">\n            <div class=\"ds-faq-item\">\n                <h4>Có cần đặt lịch hẹn trước khi đến Showroom không?</h4>\n                <p>Bạn có thể ghé thăm bất cứ lúc nào trong khung giờ 08:30 – 21:30. Tuy nhiên, chúng tôi khuyến khích đặt lịch hẹn trước để Giám đốc thiết kế bố trí thời gian tư vấn 1-1 chuyên sâu và chuẩn bị sẵn mô hình 3D phù hợp với mặt bằng nhà bạn.</p>\n            </div>\n            <div class=\"ds-faq-item\">\n                <h4>Showroom có sẵn mô hình 3D và mẫu vật liệu thực tế không?</h4>\n                <p>Có đầy đủ. Showroom trưng bày các dòng sản phẩm tiêu biểu cùng hệ thống mẫu gỗ sồi, gỗ óc chó tự nhiên, đá thiêu kết, phụ kiện bản lề Blum/Hafele và thiết bị iPad Pro để quý khách trải nghiệm trực tiếp tính năng chiếu AR vào phòng.</p>\n            </div>\n            <div class=\"ds-faq-item\">\n                <h4>DeSpace có nhận chế tác kích thước theo yêu cầu không?</h4>\n                <p>Hoàn toàn có. Với xưởng chế tác riêng, DeSpace sẵn sàng đo đạc và điều chỉnh tỷ lệ, số lượng ngăn kéo, khoang chứa đồ để vừa vặn tuyệt đối với diện tích và hốc tường của từng căn hộ.</p>\n            </div>\n            <div class=\"ds-faq-item\">\n                <h4>Chính sách giao hàng và lắp đặt được thực hiện thế nào?</h4>\n                <p>Chúng tôi miễn phí vận chuyển và lắp đặt trong nội thành Hà Nội cho các đơn hàng từ 10.000.000đ. Đội ngũ kỹ thuật viên tay nghề cao sẽ bàn giao và hướng dẫn bảo dưỡng bề mặt cẩn thận trước khi rời đi.</p>\n            </div>\n        </div>\n    </div>\n</div>\n<!-- /wp:html -->','Liên hệ','','publish','closed','closed','','lien-he','','','2026-11-14 20:32:46','2026-11-14 13:32:46','',0,'http://localhost:8090/?page_id=12',0,'page','',0),(13,0,'2026-11-14 14:51:46','2026-11-14 07:51:46','<h2>Giao hàng và đổi trả</h2><p>Liên hệ đội ngũ DeSpace để xác nhận lịch giao hàng, lắp đặt và điều kiện đổi trả.</p>','Giao hàng và đổi trả','','publish','closed','closed','','giao-hang-doi-tra','','','2026-11-14 14:51:46','2026-11-14 07:51:46','',0,'http://localhost:8090/?page_id=13',0,'page','',0),(14,0,'2026-11-14 14:51:46','2026-11-14 07:51:46','<h2>Câu hỏi thường gặp</h2><p>Đơn hàng được xử lý sau khi DeSpace xác nhận thông tin giao nhận.</p>','Câu hỏi thường gặp','','publish','closed','closed','','cau-hoi-thuong-gap','','','2026-11-14 14:51:46','2026-11-14 07:51:46','',0,'http://localhost:8090/?page_id=14',0,'page','',0),(15,0,'2026-11-14 14:51:46','2026-11-14 07:51:46','<h2>Chính sách bảo mật</h2><p>Thông tin khách hàng được WooCommerce sử dụng để xử lý đơn hàng và hỗ trợ sau mua.</p>','Chính sách bảo mật','','publish','closed','closed','','chinh-sach-bao-mat','','','2026-11-14 14:51:46','2026-11-14 07:51:46','',0,'http://localhost:8090/?page_id=15',0,'page','',0),(16,0,'2026-11-14 14:51:46','2026-11-14 07:51:46','<h2>Điều khoản mua bán</h2><p>Đơn hàng chỉ được xác nhận sau khi cửa hàng kiểm tra thông tin sản phẩm và giao nhận.</p>','Điều khoản mua bán','','publish','closed','closed','','dieu-khoan-mua-ban','','','2026-11-14 14:51:46','2026-11-14 07:51:46','',0,'http://localhost:8090/?page_id=16',0,'page','',0),(17,0,'2026-11-14 14:51:47','2026-11-14 07:51:47','','despace10','Mã demo DeSpace dùng để kiểm tra giỏ hàng và checkout.','publish','closed','closed','','despace10','','','2026-11-14 14:51:47','2026-11-14 07:51:47','',0,'http://localhost:8090/?post_type=shop_coupon&p=17',0,'shop_coupon','',0),(18,0,'2026-11-14 14:51:47','2026-11-14 07:51:47','','despace500k','Mã demo DeSpace dùng để kiểm tra giỏ hàng và checkout.','publish','closed','closed','','despace500k','','','2026-11-14 14:51:47','2026-11-14 07:51:47','',0,'http://localhost:8090/?post_type=shop_coupon&p=18',0,'shop_coupon','',0),(24,0,'2026-11-14 14:51:49','2026-11-14 07:51:49','','Sofa Bắc Âu Nord · ảnh sản phẩm','','inherit','open','closed','','sofa-bac-au-nord-%c2%b7-anh-san-pham','','','2026-11-14 14:51:49','2026-11-14 07:51:49','',0,'http://localhost:8090/?attachment_id=24',0,'attachment','image/jpeg',0),(26,0,'2026-11-14 14:51:49','2026-11-14 07:51:49','','Bàn trà Oslo · ảnh sản phẩm','','inherit','open','closed','','ban-tra-oslo-%c2%b7-anh-san-pham','','','2026-11-14 14:51:49','2026-11-14 07:51:49','',0,'http://localhost:8090/?attachment_id=26',0,'attachment','image/jpeg',0),(28,0,'2026-11-14 14:51:50','2026-11-14 07:51:50','','Giường ngủ Aurora Queen · ảnh sản phẩm','','inherit','open','closed','','giuong-ngu-aurora-queen-%c2%b7-anh-san-pham','','','2026-11-14 14:51:50','2026-11-14 07:51:50','',0,'http://localhost:8090/?attachment_id=28',0,'attachment','image/jpeg',0),(30,0,'2026-11-14 14:51:50','2026-11-14 07:51:50','','Ghế thư giãn Arc · ảnh sản phẩm','','inherit','open','closed','','ghe-thu-gian-arc-%c2%b7-anh-san-pham','','','2026-11-14 14:51:50','2026-11-14 07:51:50','',0,'http://localhost:8090/?attachment_id=30',0,'attachment','image/jpeg',0),(34,0,'2026-11-14 14:51:50','2026-11-14 07:51:50','','Tủ giày Skyline · ảnh sản phẩm','','inherit','open','closed','','tu-giay-skyline-%c2%b7-anh-san-pham','','','2026-11-14 14:51:50','2026-11-14 07:51:50','',0,'http://localhost:8090/?attachment_id=34',0,'attachment','image/webp',0),(35,0,'2026-11-14 14:51:51','2026-11-14 07:51:51','','Tủ giày Skyline · GLB','','inherit','open','closed','','tu-giay-skyline-%c2%b7-glb','','','2026-11-14 14:51:51','2026-11-14 07:51:51','',0,'http://localhost:8090/?attachment_id=35',0,'attachment','model/gltf-binary',0),(41,0,'2026-11-14 15:28:16','2026-11-14 08:28:16','<h2>Liên hệ DeSpace</h2><p>Email: <a href=\"mailto:support@despace.test\">support@despace.test</a></p><p>Đây là cửa hàng demo local; hãy thay thông tin liên hệ trước khi công bố.</p>','Liên hệ','','inherit','closed','closed','','12-revision-v1','','','2026-11-14 15:28:16','2026-11-14 08:28:16','',12,'http://localhost:8090/?p=41',0,'revision','',0),(46,0,'2026-11-14 15:28:19','2026-11-14 08:28:19','<h3>Giải pháp lưu trữ thông minh &amp; Hiển thị trực quan thông số khi di chuột (Hover)</h3>\n<p>Được khai thác từ bộ sưu tập Storage Units của DeSpace (<code>https://despace.vn/products/despace-metro-three-door-shoe-cabinet-linear</code>), <strong>Tủ giày 3 cánh DeSpace Metro - Vân gỗ Linear</strong> mang đến sự ngăn nắp tối đa cho không gian sống hiện đại. Với kích thước tổng thể <strong>Rộng 114 cm × Sâu 33 cm × Cao 76 cm</strong>, sản phẩm dễ dàng bố trí sát tường, cạnh cửa ra vào hoặc trong góc phòng mà không chiếm diện tích lối đi.</p>\n<p>Đặc biệt, sản phẩm tích hợp <strong>Thư viện ảnh đa góc chụp (Multi-view Hover Gallery)</strong>: khi khách hàng di chuột (hover) vào thẻ sản phẩm trên trang danh mục, hệ thống sẽ chuyển đổi sang ảnh chi tiết mô tả kích thước (chiều dài, chiều sâu, chiều cao), cấu trúc ngăn kệ bên trong và phối cảnh thực tế.</p>\n<h4>Điểm nhấn Chế tác &amp; Thiết kế</h4>\n<ul>\n  <li><strong>Chất liệu Tuyển chọn:</strong> Gỗ công nghiệp phủ Laminate mờ 17mm, Cánh chớp thoáng khí — kết cấu ván ép tỷ trọng cao chống cong vênh, mối mọt và thích ứng tốt với khí hậu nhiệt đới.</li>\n  <li><strong>Hoàn thiện Bề mặt:</strong> Phủ lớp Laminate / Melamine vân gỗ Vân gỗ Linear, Gỗ óc chó Columbia, Nâu Wenge chống trầy xước, chống bám bẩn và dễ dàng lau sạch.</li>\n  <li><strong>Cấu trúc Ngăn chứa Khoa học:</strong> Thiết kế gồm 3 cánh tủ, 4 tầng kệ và 0 ngăn kéo — đáp ứng sức chứa <strong>18 đôi giày</strong>.</li>\n  <li><strong>Hiển thị Hover Trực quan:</strong> Bộ ảnh Gallery đi kèm đầy đủ góc chụp chính diện, ảnh đo kích thước (Dimension View), ảnh mở cánh tủ (Interior View) và ảnh phối cảnh phòng (Room Setting).</li>\n</ul>\n<h4>Thông số kỹ thuật &amp; kích thước</h4>\n<ul>\n  <li><strong>Kích thước lắp đặt (Rộng × Sâu × Cao):</strong> 114 cm × 33 cm × 76 cm (44.9\" × 13.0\" × 29.9\")</li>\n  <li><strong>Trọng lượng tịnh:</strong> 34.0 kg</li>\n  <li><strong>Cấu hình lưu trữ:</strong> 3 Cánh cửa | 4 Ngăn kệ | 0 Ngăn kéo (18 đôi giày)</li>\n  <li><strong>Tùy chọn Màu sắc / Hoàn thiện:</strong> Vân gỗ Linear, Gỗ óc chó Columbia, Nâu Wenge</li>\n  <li><strong>Giá niêm yết &amp; Khuyến mãi (VND):</strong> <del>2,700,000 ₫</del> → <strong>2,100,000 ₫</strong></li>\n  \n  <li><strong>Không gian phù hợp:</strong> Living Room (Tông ánh sáng: Warm)</li>\n</ul>\n<h4>Hướng dẫn Bảo quản &amp; Lắp đặt</h4>\n<p>Lau bề mặt định kỳ bằng khăn mềm khô hoặc hơi ẩm; không dùng hóa chất tẩy rửa mạnh có chứa dung môi. Đặt các vật nặng ở tầng kệ dưới cùng để giữ trọng tâm vững chắc và sử dụng bộ ngàm chống lật gắn tường đi kèm đối với các mẫu tủ cao.</p>\n<p><em>Sản phẩm chính hãng nhập khẩu theo tiêu chuẩn DeSpace Storage Collection — Giao hàng đóng kiện phẳng (Flat-pack) bảo vệ góc cạnh kèm sách hướng dẫn lắp đặt chi tiết.</em></p>','Tủ giày 3 cánh DeSpace Metro - Vân gỗ Linear','Tủ giày 3 cánh DeSpace Metro - Vân gỗ Linear thiết kế tối ưu diện tích (Rộng 114 × Sâu 33 × Cao 76 cm), sức chứa 18 đôi giày, chế tác từ gỗ công nghiệp phủ laminate mờ 17mm, cánh chớp thoáng khí kèm bộ ảnh chi tiết kích thước khi di chuột (hover).','publish','open','closed','','tu-giay-3-canh-despace-metro-van-go-linear','','','2026-11-14 20:28:41','2026-11-14 13:28:41','',0,'http://localhost:8090/product/tu-giay-3-canh-axgnud-metro-van-go-linear/',0,'product','',3),(47,0,'2026-11-14 15:28:19','2026-11-14 08:28:19','','Tủ giày 3 cánh DeSpace Metro - Vân gỗ Linear · ảnh đại diện','','inherit','open','closed','','tu-giay-3-canh-axgnud-metro-van-go-linear-%c2%b7-anh-dai-dien','','','2026-11-14 16:27:09','2026-11-14 09:27:09','',46,'http://localhost:8090/?attachment_id=47',0,'attachment','image/jpeg',0),(48,0,'2026-11-14 15:28:20','2026-11-14 08:28:20','','Tủ giày 3 cánh DeSpace Metro - Vân gỗ Linear · ảnh 1','','inherit','open','closed','','tu-giay-3-canh-axgnud-metro-van-go-linear-%c2%b7-anh-1','','','2026-11-14 16:27:09','2026-11-14 09:27:09','',46,'http://localhost:8090/?attachment_id=48',0,'attachment','image/jpeg',0),(49,0,'2026-11-14 15:28:20','2026-11-14 08:28:20','','Tủ giày 3 cánh DeSpace Metro - Vân gỗ Linear · ảnh 2','','inherit','open','closed','','tu-giay-3-canh-axgnud-metro-van-go-linear-%c2%b7-anh-2','','','2026-11-14 16:27:09','2026-11-14 09:27:09','',46,'http://localhost:8090/?attachment_id=49',0,'attachment','image/jpeg',0),(50,0,'2026-11-14 15:28:21','2026-11-14 08:28:21','','Tủ giày 3 cánh DeSpace Metro - Vân gỗ Linear · ảnh 3','','inherit','open','closed','','tu-giay-3-canh-axgnud-metro-van-go-linear-%c2%b7-anh-3','','','2026-11-14 16:27:09','2026-11-14 09:27:09','',46,'http://localhost:8090/?attachment_id=50',0,'attachment','image/png',